def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    # step 1: enclosed background (not touching border) -> 4
    for comp in components(g == bg):
        if not any(y in (0, H-1) or x in (0, W-1) for y, x in comp):
            for y, x in comp:
                out[y, x] = 4
    emit(out, "Fill enclosed cyan (8) holes inside the magenta (6) objects with yellow (4).")
    # step 2: green ring around each object's bounding box, onto background only
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        for y in range(max(0, y0-1), min(H, y1+2)):
            for x in range(max(0, x0-1), min(W, x1+2)):
                if (y < y0 or y > y1 or x < x0 or x > x1) and out[y, x] == bg:
                    out[y, x] = 3
        emit(out, f"Draw a green (3) ring on the cyan (8) background around the magenta (6) object with bounding box {o['box']}.")
    return out
